def calculate_power_of_divisor(P, D):
    """
    Calculates the maximum integer e such that D^e divides P.
    Returns 0 if D=0 (though D!=0 is guaranteed).
    Returns a large number if D=1 (as 1^e always divides P).
    """
    if D == 1:
        # Since the problem constraints say b-a != 0, d=1 is possible.
        # For d=1, d^n = 1, which always divides P. We treat this case as
        # yielding a trivial upper bound for the numerical test, as it won't
        # constrain n.
        return float('inf')

    if P == 0:
        # If P=0, it's divisible by any power of D.
        return float('inf')

    e = 0
    temp_P = abs(P)
    temp_D = abs(D)

    # Check divisibility iteratively
    while temp_P > 0 and temp_D > 1:
        if temp_P % temp_D == 0:
            temp_P //= temp_D
            e += 1
        else:
            break
    return e

# --- Polynomial P1 ---
# P1(x, y, z) = (x-y)^2 + (y-z)^2
def P1(x, y, z):
    return (x - y)**2 + (y - z)**2

# --- Polynomial P2 ---
# P2(x, y, z) = (x-y)^2 + (x-z)^2 + (y-z)^2
def P2(x, y, z):
    return (x - y)**2 + (x - z)**2 + (y - z)**2

# --- Test Cases ---
tests = {
    "P1": {
        "AP_123": (1, 2, 3), # d=1
        "AP_135": (1, 3, 5)  # d=2
    },
    "P2": {
        "AP_123": (1, 2, 3), # d=1
        "AP_135": (1, 3, 5)  # d=2
    }
}

results = {}

for name, polys in tests.items():
    results[name] = {}
    for ap_name, (a, b, c) in polys.items():
        d = b - a

        # Test P1
        p1_val = P1(a, b, c)
        e1 = calculate_power_of_divisor(p1_val, d)

        # Test P2
        p2_val = P2(a, b, c)
        e2 = calculate_power_of_divisor(p2_val, d)

        results[name][ap_name] = {
            'd': d,
            'P1_value': p1_val,
            'P1_exponent': e1,
            'P2_value': p2_val,
            'P2_exponent': e2
        }

print("--- Results ---")
for p_name, ap_results in results.items():
    print(f"\nPolynomial {p_name}:")
    for ap_name, res in ap_results.items():
        print(f"  AP {ap_name} (d={res['d']}):")

        if res['d'] == 1:
            print(f"    P1({ap_name})={res['P1_value']}. d=1 yields infinite power.")
            print(f"    P2({ap_name})={res['P2_value']}. d=1 yields infinite power.")
        else:
            print(f"    P1({ap_name})={res['P1_value']}. Max exponent e such that d^e | P1 is: {res['P1_exponent']}")
            print(f"    P2({ap_name})={res['P2_value']}. Max exponent e such that d^e | P2 is: {res['P2_exponent']}")
